CREATE TABLE accounts(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,type TEXT NOT NULL,closing INTEGER NOT NULL,charge INTEGER NOT NULL,credit_limit INTEGER NOT NULL,payment INTEGER NOT NULL,opening INTEGER NOT NULL,start TEXT NOT NULL)
CREATE TABLE rules(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,amount INTEGER NOT NULL,account INTEGER NOT NULL REFERENCES accounts(id),category TEXT NOT NULL,start TEXT NOT NULL,end TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1)
CREATE TABLE transactions(id INTEGER PRIMARY KEY AUTOINCREMENT,date TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>0),category TEXT NOT NULL,merchant TEXT NOT NULL,note TEXT NOT NULL,tag TEXT NOT NULL,account INTEGER NOT NULL REFERENCES accounts(id),kind TEXT NOT NULL,count INTEGER NOT NULL CHECK(count BETWEEN 1 AND 120),status INTEGER NOT NULL,rule INTEGER REFERENCES rules(id),UNIQUE(rule,date))
CREATE INDEX tx_date ON transactions(date)
